<?php
if(PHP_SAPI!=='cli'||getenv('APP_ENV')!=='testing'||!preg_match('/^impe_test_handly_aliados_v4_v5_[a-z0-9_]+$/D',getenv('IMPE_DB_NAME')?:''))exit(2);
require_once __DIR__.'/../app/models/ConvocatoriaModel.php';
$m=new ConvocatoriaModel();$db=$m->conexionLote();$n=0;
$check=static function($v,$message)use(&$n){if(!$v)throw new RuntimeException($message);$n++;echo "OK $message\n";};
$rows=$m->obtenerListado('',1,'','','bachillerato');$byTitle=array_column($rows,null,'titulo');
$check(count($rows)===count(array_unique(array_column($rows,'id'))),'cada ID aparece una vez aunque haya relaciones históricas duplicadas');
$check($byTitle['Título independiente del aliado']['aliado']['nombre']==='IQJ','identidad V3 explícita sin depender del título ni del enlace');
$check($byTitle['Título sin nombre institucional']['aliado']['procedencia']==='Vinculación','relación histórica verificable');
$check($byTitle['Convocatoria territorial histórica']['aliado']['procedencia']==='Publicación territorial'&&!$byTitle['Convocatoria territorial histórica']['aliado']['tiene_relacion'],'territorial sin aliado ficticio');
$check($byTitle['Relación contradictoria']['aliado']['estado']==='revision','relaciones distintas se señalan sin elegir arbitrariamente');
$check($byTitle['Publicación internacional']['aliado']['procedencia']==='Aliado internacional','origen internacional desde formulario_aliados');
$check(count($m->obtenerListado('IQJ',1,'','','bachillerato'))===2,'buscar aliado no requiere título coincidente');
$check(count($m->obtenerListado('Bachillerato General',1,'','','bachillerato'))===5,'buscar nombre canónico del programa');
$manual=$m->obtenerListado('',2,'','','titulacion','experiencia-laboral');
$check(count($manual)===1&&$manual[0]['aliado']['nombre']==='V4 Manual'&&$manual[0]['aliado']['procedencia']==='Aliado manual','origen manual independiente y sin duplicación por dos vínculos');
$check(count($m->obtenerListado('',1,'','','bachillerato','ingles'))===1,'modalidad específica en servidor');
$check(count($m->obtenerListado('',2,'','','bachillerato'))===0,'segmentación conserva territorio');
$check(count($m->obtenerListado('',1,'0','','bachillerato'))===1,'historial incluye publicación desactivada');
$r=$byTitle['Título independiente del aliado'];$data=array_merge($r,['usuario_id'=>4]);$data['enlace_registro']='https://example.test/manipulado';
$check(!$m->actualizar((int)$r['id'],$data,[1]),'modelo rechaza alterar enlace del aliado incluso sin controlador');
$data['enlace_registro']=$r['enlace_registro'];$data['subtipo_convocatoria']='ingles';
$check(!$m->actualizar((int)$r['id'],$data,[1]),'modelo rechaza sustituir el programa asociado');
$data['subtipo_convocatoria']=$r['subtipo_convocatoria'];$data['titulo']='Edición DB verificada';
$check($m->actualizar((int)$r['id'],$data,[2]),'edición legítima conserva el estado real del aliado');
$saved=$m->buscarPorId((int)$r['id']);$check($saved['estados_ids']===[1]&&$saved['aliado']['id']===10&&$saved['enlace_registro']===$r['enlace_registro'],'relación y territorio no cambian por estados manipulados');
$data['titulo']=$r['titulo'];$m->actualizar((int)$r['id'],$data,[1]);
$check((int)$db->query('SELECT COUNT(*) FROM convocatoria_borradores')->fetch_row()[0]===0,'listado y edición no crean ni publican borradores V4');
echo "PASS $n comprobaciones V5 DB\n";
